  "coach.project.primary.title": "La prochaine étape est ici",
  "coach.project.primary.body": "Ce bouton indique l'action suivante : publier le projet, puis publier les scores une fois la correction terminée.",
  "coach.project.repos.title": "Un dépôt par étudiant",
  "coach.project.repos.body": "Le dépôt de chaque étudiant apparaît sous cet onglet dès que l'étudiant a accepté le projet, avec son dernier commit et ses vérifications.",
  "coach.project.repo.title": "Ouvrir un dépôt",
  "coach.project.repo.body": "Cliquez sur une ligne pour ouvrir sa fiche : vérifications, exécutions, score et échéance individuelle.",
