  "settings.coach": "Bulles de découverte",
  "settings.coachHint": "Des bulles présentent chaque écran à sa première ouverture.",
  "settings.festive": "Touches festives",
  "settings.festiveHint": "Certains jours (Noël, journée de π…), le logo change et une animation s'affiche. Jamais en évaluation.",
  "festive.about": "{name} : en savoir plus",
  "festive.wikipedia": "Lire sur Wikipédia",
  "festive.programmers.title": "Bonne journée des programmeurs",
  "festive.programmers.text": "Le 256ᵉ jour de l'année : 0x100, ou 2⁸, le nombre de valeurs d'un octet. Il tombe le 13 septembre, le 12 les années bissextiles, au début du semestre. Bonne rentrée.",
  "festive.programmers.wiki": "Journée des programmeurs",
  "festive.ada.title": "Journée Ada Lovelace",
  "festive.ada.text": "Le deuxième mardi d'octobre célèbre les femmes en sciences et en technique, au nom d'Ada Lovelace. En 1843, ses notes sur la machine analytique de Charles Babbage décrivent un algorithme de calcul des nombres de Bernoulli, souvent tenu pour le premier programme publié.",
  "festive.ada.wiki": "Ada Lovelace Day",
  "festive.hopper.title": "Joyeux anniversaire, Grace Hopper",
  "festive.hopper.text": "Née le 9 décembre 1906 à New York, elle est une pionnière des compilateurs et ses travaux ont mené à COBOL. Elle aimait raconter l'histoire de la mite trouvée en 1947 dans un relais du Harvard Mark II et collée dans son journal de bord : « First actual case of bug being found ».",
  "festive.hopper.wiki": "Grace Hopper",
  "festive.xmas.title": "Joyeuses fêtes",
  "festive.xmas.text": "Le semestre d'automne s'achève, la session d'examens approche. Bonnes fêtes, et bon repos avant la reprise.",
  "festive.xmas.wiki": "Noël",
  "festive.torvalds.title": "Joyeux anniversaire, Linus Torvalds",
  "festive.torvalds.text": "Né le 28 décembre 1969 à Helsinki. Étudiant, il annonce en août 1991 un système « just a hobby, won't be big and professional like gnu » : le noyau Linux. En 2005, il écrit aussi Git.",
  "festive.torvalds.wiki": "Linus Torvalds",
  "festive.kernighan.title": "Joyeux anniversaire, Brian Kernighan",
  "festive.kernighan.text": "Né le 30 janvier 1942 à Toronto. Son tutoriel du langage B (1972) contient le premier « hello, world » connu. En 1978, il signe avec Dennis Ritchie The C Programming Language, le « K&R ». Il est aussi le K d'AWK.",
  "festive.kernighan.wiki": "Brian Kernighan",
  "festive.pi.title": "Bonne journée de π",
  "festive.pi.text": "Le 14 mars s'écrit 3/14 à l'américaine. La journée est fêtée depuis 1988 à l'Exploratorium de San Francisco. C'est aussi l'anniversaire d'Albert Einstein (1879).",
  "festive.pi.wiki": "Journée de pi",
  "festive.easter.title": "Joyeuses Pâques",
  "festive.easter.text": "Pâques tombe le dimanche qui suit la première pleine lune du printemps. Sa date se calcule (Gauss, puis Meeus), un exercice de programmation classique : la fonction qui a posé ces oreilles sur le U en est un.",
  "festive.easter.wiki": "Calcul de la date de Pâques",
  "festive.starwars.title": "May the 4th be with you",
  "festive.starwars.text": "Un jeu de mots sur « May the Force be with you » : le 4 mai est devenu la journée des fans de Star Wars, bien au-delà des cinémas.",
  "festive.starwars.wiki": "Journée Star Wars",
  "festive.turing.title": "Joyeux anniversaire, Alan Turing",
  "festive.turing.text": "Né le 23 juin 1912 à Londres. En 1936, il décrit une machine abstraite (un ruban, une tête de lecture, une table de règles) qui définit encore ce que « calculable » veut dire.",
  "festive.turing.wiki": "Alan Turing",
